#!/usr/bin/env python3
# MEER v4.51 layout patch (HTML only) — repo-form ship script.
# Local chain (tasalli-verified) ka repo roop: patch_v451_layout ->
# patch_v451_ver. Har stage ka source NECHAY VERBATIM embedded hai
# (anchors/asserts bilkul wahi jo local built-v451-final.html (MD5
# d861dad8ee7da81b54acb62798e08450) banane me istemal hue).
# Stage feeding: layout stage apne hi folder se
# 'built-v450-final3.html' parhta hai aur 'built-v451-layout.html'
# likhta hai — is liye driver temp dir me input ko wahi naam deta
# hai, jis se us ka MD5 guard (5dff7139f87765a0a5290b650c38f9bf)
# bilkul local chain ki tarah fire hota hai. Ver stage ka MD5 guard
# input file ke NAAM ('built-v451-layout.html') par trigger hota
# hai — driver argv me wahi naam deta hai.
# Chalana: repo root se  python3 patch_v451.py
# Target: android/app/src/main/assets/www/index.html (workflow ki
# "Sync web assets" + v389..v449 + v4.50 steps ke BAAD ki haalat par).
# Is version me Java / manifest ki KOI tabdeeli nahi hai.
import hashlib
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HP = ROOT / 'android/app/src/main/assets/www/index.html'

STAGES = [
    ('stage_layout.py', '#!/usr/bin/env python3\n# MEER v4.51 LAYOUT patch — LOCAL ONLY (sim-meer2).\n# GitHub upload / APK build is patch ka kaam NAHI hai.\n#\n# BASE: built-v450-final3.html (MD5 5dff7139f87765a0a5290b650c38f9bf).\n# Base file kabhi modify NAHI hoti — copy par kaam karke\n# built-v451-layout.html likhi jati hai. JAVA bilkul nahi chhuya.\n#\n# Hamza ki do shikayatein (2026-10-22):\n#   A) "In sub ko ak he jaga hona chahye" — New Adventure, Real Video,\n#      Single Journey, Aaj Ki Video bikhre hue lagte hain.\n#   B) s-real par horizontal overflow — "Characters ke naam" wali card\n#      me teesra naam (Rusty) screen se bahir; side par slide karna\n#      parta hai. Uske alfaaz: "inko ak he page mn kro, chota kro ya\n#      jo bhi kro."\n#\n# INVESTIGATION (code se sabit):\n#   - Chaaron asal buttons asal me s-real par hi hain (Real Cartoon\n#     Studio): REAL VIDEO BANAO (line ~692, onclick realMakeVideo),\n#     SINGLE CAR JOURNEY (~693), Aaj Ki Video (~694,\n#     id=meerQuickJourneyBtn). NEW ADVENTURE ka button markup me hai\n#     hi NAHI — runtime par aik IIFE use REAL VIDEO BANAO wale button\n#     ke foran baad insert karta hai (id=advBtn). Masla jagah ka nahi,\n#     RASTE ka hai: home se in tak pohanchne ka saaf aik-jaga index\n#     nahi tha.\n#   - Journey button ki binding ID se NAHI hai: do jagah\n#     document-wide TEXT search (\'SINGLE CAR JOURNEY\') se rebind\n#     hota hai (aik 5-second interval par bhi). Text-bound button ko\n#     move karna risky — is liye KOI asal button move NAHI hua.\n#   - Quick button (id-based) bhi move NAHI kiya: uska poora flow\n#     (journeyV3) progress/status s-real ke hi elements (realBar,\n#     realProg, realStat, realPreview) par dikhata hai; s-video se\n#     chalane par user ko khaali screen par intezaar karna parta.\n#   - Isi liye design: naya TOP-LEVEL screen "s-video" (🎬 Video\n#     Banao) — chaaron options aik card me tartib se, har button\n#     go(\'s-real\');realInit() wala WAHI purana rasta leta hai jo home\n#     ka Real Cartoon Studio tile leta hai, aur phir asal button ko\n#     scroll karke samne la deta hai (home ke Suspense buttons wala\n#     scrollIntoView tareeqa). Naye buttons ke text jaan-boojh kar\n#     woh substrings NAHI rakhte jin par purane text-search loops\n#     chalte hain (\'SINGLE CAR JOURNEY\' / \'REAL VIDEO BANAO\' —\n#     case-sensitive ALL-CAPS); labels Title Case me hain.\n#   - Overflow ki wajah (code): .row{display:flex} + .row>*{flex:1},\n#     lekin flex items ki default min-width:auto input ke intrinsic\n#     size (~170px+) se neeche shrink hone nahi deti — 3 naam boxes\n#     + gaps phone width se baray ho jate hain. Wahi pattern\n#     realFamName1/2/3 (s-realfam) me bhi hai — input.big-idea wale\n#     saare 6 naam inputs aik hi CSS rule se fit honge. Poori file me\n#     aur koi fixed-width overflow saboot NAHI mila (width:320/560px\n#     dono max-width hain — cap karte hain, majboor nahi karte).\n#\n# TABDEELIYAN (sirf ye teen — koi function/flow NAHI badla):\n#   1. CSS (head <style>, .row wali line ke foran baad):\n#      .row>*{min-width:0}; input,select,textarea{max-width:100%;\n#      min-width:0}; input.big-idea{font-size:14px;padding:10px 8px}\n#      (sirf 6 naam inputs — "chota kro" ki ijazat se);\n#      html,body{overflow-x:hidden}; .screen{overflow-x:hidden}\n#      (global guard — vertical layout bilkul nahi chhuya).\n#   2. Home par tile "🎬 Video Banao" (Real Cartoon Studio wali row\n#      se foran pehle) -> go(\'s-video\').\n#   3. Naya top-level screen s-video (s-videos ke foran baad, kisi\n#      screen ke andar nested NAHI) + chhota sa navigation helper\n#      meerGotoReal() (sirf navigation + scroll — koi flow nahi).\n#\n# Har anchor assert hota hai; anchor na mile to patch ruk jata hai.\n\nimport hashlib\nimport re\nfrom collections import Counter\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = HERE / \'built-v450-final3.html\'\nDST = HERE / \'built-v451-layout.html\'\n\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nraw = SRC.read_bytes()\nmd5 = hashlib.md5(raw).hexdigest()\nassert md5 == \'5dff7139f87765a0a5290b650c38f9bf\', f\'base MD5 galat: {md5} — patch ROK diya\'\nhtml = raw.decode(\'utf-8\')\norig_len = len(html)\n\n\ndef rep(old, new, label):\n    global html\n    n = html.count(old)\n    assert n == 1, f\'anchor [{label}] {n} dafa mila (1 chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new, 1)\n    print(f\'{label}: OK\')\n\n\n# =====================================================================\n# 1. CSS — overflow fix + global guard (.row wali line ke baad)\n# =====================================================================\nrep(\n    \'.row{display:flex;gap:8px}.row>*{flex:1}\',\n    \'.row{display:flex;gap:8px}.row>*{flex:1}\\n\'\n    \'/* v4.51 layout fix: flex rows ke andar form controls shrink hon \'\n    \'(default min-width:auto input ke intrinsic size se rok deta tha — \'\n    \'yehi s-real ke naam wale overflow ki wajah thi) + global overflow guard */\\n\'\n    \'.row>*{min-width:0}\\n\'\n    \'input,select,textarea{max-width:100%;min-width:0}\\n\'\n    \'input.big-idea{font-size:14px;padding:10px 8px}\\n\'\n    \'html,body{overflow-x:hidden}\\n\'\n    \'.screen{overflow-x:hidden}\',\n    \'CSS overflow fix + guard\',\n)\n\n# =====================================================================\n# 2. Home tile — "🎬 Video Banao" (Real Cartoon Studio row se pehle)\n# =====================================================================\nreal_tile = (\n    \'  <div class="row">\\n\'\n    \'    <button class="btn" onclick="go(\\\'s-real\\\');realInit()" \'\n    \'style="background:linear-gradient(135deg,#00c9ff,#92fe9d);color:#003">\'\n    \'🎬 Real Cartoon Studio</button>\\n\'\n    \'  </div>\'\n)\nrep(\n    real_tile,\n    \'  <div class="row">\\n\'\n    \'    <button class="btn" onclick="go(\\\'s-video\\\')" \'\n    \'style="background:linear-gradient(135deg,#06b6d4,#8b5cf6)">\'\n    \'🎬 Video Banao</button>\\n\'\n    \'  </div>\\n\'\n    + real_tile,\n    \'Home tile Video Banao\',\n)\n\n# =====================================================================\n# 3. Naya top-level screen s-video + navigation helper meerGotoReal()\n#    (s-videos screen ke foran baad)\n# =====================================================================\ns_video_block = \'\'\'\n<!-- ============ VIDEO BANAO HUB (v4.51 layout) ============ -->\n<div class="screen" id="s-video">\n  <button class="back" onclick="go(\'s-home\')">← Home</button>\n  <h1 style="font-size:22px">🎬 Video Banao</h1>\n  <p class="hint">Saare video wale options aik hi jagah 👇 Jo chuno ge, us ka studio khul jayega aur wahi button chamak kar samne aa jayega.</p>\n  <div class="card">\n    <button class="btn btn2" onclick="meerGotoReal(\'journey\')">🚗 Single Car Journey</button>\n    <p class="hint">Aik car, poem ke saath lambi drive — online library ki kahani, har line ka apna scene.</p>\n    <button class="btn" onclick="meerGotoReal(\'quick\')" style="margin-top:10px;background:linear-gradient(135deg,#f59e0b,#ef4444);color:#fff">🚗 Aaj Ki Video</button>\n    <p class="hint">Jo car aur waqt aakhri dafa chuna tha — aik tap me wohi journey dobara.</p>\n    <button class="btn" onclick="meerGotoReal(\'adv\')" style="margin-top:10px;background:linear-gradient(90deg,#ff9a56,#ff5e8a);color:#fff">🗺 New Adventure</button>\n    <p class="hint">Rayo, Bella aur Rusty — naye scenes aur awaz ke saath adventure video.</p>\n    <button class="btn btn3" onclick="meerGotoReal(\'real\')" style="margin-top:10px">🎬 Real Video</button>\n    <p class="hint">Apni script aur characters ke naam — asli cartoon clips se poori video.</p>\n  </div>\n</div>\n\n<script>\n/* ===== MEER v4.51 layout: Video Banao hub ke navigation buttons =====\n   Sirf navigation hai — koi flow NAHI badla. Chaaron asal buttons\n   Real Cartoon Studio (s-real) par hi hain (journey wala text-search\n   se bind hota hai, adventure wala runtime par REAL VIDEO wale\n   button ke baad banta hai, quick/real ke controls s-real par hain);\n   ye helper wahan pohanch kar wahi button samne la deta hai — home\n   ke Suspense buttons wala purana tareeqa (go + scrollIntoView). */\nfunction meerGotoReal(which){\n  go(\'s-real\');\n  try{ realInit(); }catch(e){}\n  setTimeout(function(){\n    var el=null;\n    if(which===\'quick\'){ el=document.getElementById(\'meerQuickJourneyBtn\'); }\n    else if(which===\'adv\'){ el=document.getElementById(\'advBtn\'); }\n    if(!el){\n      var want=(which===\'journey\')?\'SINGLE CAR JOURNEY\':\'REAL VIDEO BANAO\';\n      var btns=document.querySelectorAll(\'button\');\n      for(var i=0;i<btns.length;i++){ if(btns[i].textContent.indexOf(want)>=0){ el=btns[i]; break; } }\n    }\n    if(el){ try{ el.scrollIntoView({block:\'center\'}); }catch(e){}\n      try{ var old=el.style.outline; el.style.outline=\'3px solid #ffd166\'; setTimeout(function(){ el.style.outline=old; },1600); }catch(e){} }\n  },600);\n}\n</script>\'\'\'\n\nrep(\n    \'  <div id="meerVideosList"></div>\\n</div>\',\n    \'  <div id="meerVideosList"></div>\\n</div>\' + s_video_block,\n    \'s-video screen + meerGotoReal helper\',\n)\n\n# =====================================================================\n# Final asserts\n# =====================================================================\nassert html.count(\'id="s-video"\') == 1, \'final: s-video aik hi dafa\'\nassert html.count("go(\'s-video\')") == 1, \'final: home tile aik hi\'\nassert html.count(\'function meerGotoReal(\') == 1, \'final: helper aik hi\'\nassert html.count(\'v4.51 layout fix\') == 1, \'final: CSS marker aik hi\'\nassert html.count(\'input.big-idea{font-size:14px\') == 1, \'final: naam CSS aik hi\'\n# Asal buttons apni jagah par hi (move NAHI hue)\nassert html.count(\'SINGLE CAR JOURNEY (poem + drive!)\') == 1, \'final: journey button barqarar\'\nassert html.count(\'id="meerQuickJourneyBtn"\') == 1, \'final: quick button barqarar\'\nassert html.count(\'onclick="realMakeVideo()"\') == 1, \'final: real video button barqarar\'\nfor nid in (\'realName1\', \'realName2\', \'realName3\', \'realFamName1\', \'realFamName2\', \'realFamName3\'):\n    assert html.count(f\'id="{nid}"\') == 1, f\'final: {nid} barqarar\'\n# Duplicate ids poore document me na hon (base me bhi nahi thay)\nids = re.findall(r\'\\bid="([^"]+)"\', html)\ndups = [k for k, v in Counter(ids).items() if v > 1]\nassert not dups, f\'final: duplicate ids aa gaye: {dups}\'\n# s-video kisi screen ke andar nested na ho: us se pehle aakhri screen\n# open tag s-videos hai aur uska close s-video se pehle aa chuka hai\ni_sv = html.index(\'id="s-video"\')\ni_svideos = html.index(\'id="s-videos"\')\nassert i_svideos < i_sv, \'final: s-video s-videos ke baad hai\'\nseg = html[i_svideos:i_sv]\nassert seg.count(\'<div class="screen"\') == 1 and \'</div>\' in seg, \'final: s-videos band ho chuki hai s-video se pehle\'\n\nDST.write_text(html, encoding=\'utf-8\')\nout_md5 = hashlib.md5(html.encode(\'utf-8\')).hexdigest()\nprint(f\'WROTE {DST} ({len(html)} chars; base se {len(html) - orig_len:+d})\')\nprint(f\'OUT MD5: {out_md5}\')\nprint(\'v4.51 LAYOUT patch done\')\n'),
    ('stage_ver.py', '#!/usr/bin/env python3\n# MEER v4.51 VERSION patch — sirf version pehchan 4.50 -> 4.51 — LOCAL ONLY\n# (sim-meer2). GitHub upload / APK build is patch ka kaam NAHI hai.\n#\n# BASE: built-v451-layout.html (MD5 de202d5727ada2c03d2aa12a2cfcb9ca) —\n# v4.51 layout build (naya s-video screen + overflow CSS fix; harness\n# 135/0, JS gate PASS). Base file kabhi modify NAHI hoti — copy par\n# kaam karke built-v451-final.html likhi jati hai.\n#\n# Sirf teen user-visible/functional version strings badalte hain,\n# bilkul v4.50 part4 ke A-round wale tareeqe se (full anchors,\n# exactly-once assert). Code comments me maujood "4.50" wale alfaaz\n# NAHI chhoote (wo purani rounds ke record hain).\n#\n# Har anchor assert hota hai; anchor na mile to patch ruk jata hai.\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v451-layout.html\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v451-final.html\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v451-layout.html\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'de202d5727ada2c03d2aa12a2cfcb9ca\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nhtml = SRC.read_text(encoding=\'utf-8\')\norig = html\napplied = []\n\n\ndef rep(old, new, label):\n    global html\n    n = html.count(old)\n    assert n == 1, f\'anchor [{label}] {n} dafa mila (1 chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new)\n    applied.append(label)\n\n\n# ---------- Version strings: 4.50 -> 4.51 ----------\nrep(\'const APP_VER="4.50";\',\n    \'const APP_VER="4.51";\',\n    \'V1 APP_VER\')\n\nrep(\'>v4.50 MEER • 100% Free • No watermark<\',\n    \'>v4.51 MEER • 100% Free • No watermark<\',\n    \'V2 footer\')\n\nrep(\'id="verLabel" style="opacity:.6;font-size:12px">v4.50<\',\n    \'id="verLabel" style="opacity:.6;font-size:12px">v4.51<\',\n    \'V3 verLabel static\')\n\n# ---------- Aakhri asserts ----------\nassert html.count(\'const APP_VER="4.51";\') == 1\nassert html.count(\'const APP_VER="4.50"\') == 0\nassert html.count(\'v4.51 MEER\') == 1 and html.count(\'v4.50 MEER\') == 0\nassert html.count(\'id="verLabel" style="opacity:.6;font-size:12px">v4.51<\') == 1\n# baqi "4.50" sirf comments/record me reh gaye hon — kul tadaad sirf\n# in teen replacements se ghategi (har aik me aik "4.50" tha)\nassert html.count(\'4.50\') == orig.count(\'4.50\') - 3, \'4.50 ki tadaad me ghair-mutawaqqa farq — patch ROK diya\'\nassert len(html) == len(orig), \'lambai badli — sirf 4.50->4.51 (barabar size) hona chahiye tha\'\n\nDST.write_text(html, encoding=\'utf-8\')\nprint(\'applied:\', \', \'.join(applied))\nprint(\'WROTE\', DST, f\'({len(html)} chars)\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'),
]


def run_stage(tmp, name, source, args=(), cwd=None):
    f = tmp / name
    f.write_text(source, encoding='utf-8')
    print(f'--- v4.51 stage {name} ---', flush=True)
    subprocess.run([sys.executable, str(f), *[str(a) for a in args]],
                   cwd=str(cwd or tmp), check=True)


def main():
    assert HP.is_file(), f'target nahi mila: {HP} — patch ROK diya'
    original = HP.read_bytes()
    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td)
        stages = dict(STAGES)
        # Stage 1: layout — script apne folder (temp dir) se
        # 'built-v450-final3.html' parhega (MD5 guard andar hai),
        # 'built-v451-layout.html' likhega. argv nahi leta.
        (tmp / 'built-v450-final3.html').write_bytes(original)
        run_stage(tmp, 'stage_layout.py', stages['stage_layout.py'], cwd=tmp)
        # Stage 2: version — argv SRC/DST; SRC ka naam
        # 'built-v451-layout.html' hote hi us ka MD5 guard fire hoga.
        run_stage(tmp, 'stage_ver.py', stages['stage_ver.py'],
                  (tmp / 'built-v451-layout.html', tmp / 'built-v451-final.html'))
        final = (tmp / 'built-v451-final.html').read_bytes()
    fmd5 = hashlib.md5(final).hexdigest()
    assert fmd5 == 'd861dad8ee7da81b54acb62798e08450', \
        f'final MD5 galat: {fmd5} — patch ROK diya (kuch nahi likha)'
    HP.write_bytes(final)
    print(f'v4.51 layout patch done: {HP} ({len(original)} -> {len(final)} bytes)')


if __name__ == '__main__':
    main()
